import{z as E,x as l,o,c as p,q as s,j as r,D as a,d,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"进程组与会话","description":"","frontmatter":{"title":"进程组与会话","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/process-groups.md","filePath":"cs/process-groups.md","lastUpdated":1791413859000}'),c={name:"cs/process-groups.md"};function B(A,e,m,P,h,_){const t=l("Mermaid");return o(),p("div",null,[e[2]||(e[2]=s('<h1 id="进程组与会话" tabindex="-1">进程组与会话 <a class="header-anchor" href="#进程组与会话" aria-label="Permalink to &quot;进程组与会话&quot;">​</a></h1><div class="epigraph"><p>进程组是可以一并发信号的作业；会话把一组进程绑到控制终端，前台组才能读终端。</p><footer>—— 据 Stevens and Rago, Advanced Programming in the UNIX Environment；Tanenbaum MOS 整理</footer></div><p><a href="/cs/exit-reap">上一课</a>让单个 PCB 能干净结束。shell 的 <code>|</code> 与后台 <code>&amp;</code> 要一次管理<strong>多个进程</strong>：Ctrl-C 应打到前台那一组，而不是随机一个 PID。<a href="/cs/signals">信号</a>能按 PID 投递。缺口是把 PCB 编成<strong>进程组</strong>与<strong>会话</strong>，并与控制终端挂钩。本课只钉这套作业控制对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>管道两端是两个 PID，用户希望「打断这条命令」时两个都停。进程组 ID（PGID）通常等于组长的 PID；<code>kill(-pgid, sig)</code> 打到组内。会话（SID）由会话首领 <code>setsid</code> 创建，脱离旧控制终端，成为守护进程的常见步骤。缺口不是再讲 wait，而是 PCB 上的 pgid/sid 与 tty 的前台组字段。</p><p><span class="marginnote">前台进程组可从终端读；后台组读终端会被 <code>SIGTTIN</code> 停下。这是作业控制，不是新的文件描述符类型。</span></p><p><span class="marginnote">「组长」就是建组时的第一个进程，PGID 通常等于它的 PID——好比以发起人命名一个项目群；组长退出后群还在，其余成员照旧属于这个组。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>setpgid</code> 把进程移入某组（受限：须在同一会话）。<code>setsid</code> 创建新会话、新组，切断控制 tty。终端驱动记住前台 PGID；收到中断字符则向该组发 <code>SIGINT</code>。orphan 进程组（组内无成员的父在同一会话）有额外停止信号规则，主干承认「后台作业与 tty 的关系要收口」，不背整章 POSIX。</p>',9)),(o(),r(n,null,{default:a(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SES%5B%22%E4%BC%9A%E8%AF%9D%22%5D%20--%3E%20FG%5B%22%E5%89%8D%E5%8F%B0%E8%BF%9B%E7%A8%8B%E7%BB%84%22%5D%0A%20%20SES%20--%3E%20BG%5B%22%E5%90%8E%E5%8F%B0%E8%BF%9B%E7%A8%8B%E7%BB%84%22%5D%0A%20%20TTY%5B%22%E6%8E%A7%E5%88%B6%E7%BB%88%E7%AB%AF%22%5D%20--%3E%20FG%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<p>fork 默认继承组与会话；exec 不改。shell 在 fork 之后、exec 之前 <code>setpgid</code>，把管道各段收进同一作业组。</p><p><span class="marginnote"><code>kill(-pgid, sig)</code> 里的负号表示「按组投递」：可以把它想象成在群里发通知而不是逐个私聊——<code>kill(-4242, SIGINT)</code> 会把信号同时送到 PGID 为 4242 的组内每一个进程，无论组里有 2 个还是 200 个成员。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>组把信号从「一个 PCB」抬到「一个作业」。与<a href="/cs/orphan-init">孤儿与 init</a>叠加：会话首领退出可能挂断终端，向前台进程组发 <code>SIGHUP</code>。调度器仍按线程选 CPU，不按组调度——组不是调度实体。组只影响信号投递与 tty 权限。</p>',4)),(o(),r(n,null,{default:a(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20K%5B%22%E7%94%A8%E6%88%B7%E6%95%B2%20Ctrl-C%22%5D%20--%3E%20D%5B%22%E7%BB%88%E7%AB%AF%E9%A9%B1%E5%8A%A8%22%5D%0A%20%20D%20--%3E%20L%5B%22%E6%9F%A5%E5%89%8D%E5%8F%B0%20PGID%22%5D%0A%20%20L%20--%3E%20S%5B%22kill%20-pgid%20%E4%B8%80%E6%AC%A1%E6%8A%95%E9%80%92%22%5D%0A%20%20S%20--%3E%20P1%5B%22%E7%AE%A1%E9%81%93%E5%B7%A6%E6%AE%B5%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20S%20--%3E%20P2%5B%22%E7%AE%A1%E9%81%93%E5%8F%B3%E6%AE%B5%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20S%20--%3E%20P3%5B%22%E7%BB%84%E5%86%85%E5%85%B6%E4%BB%96%E6%88%90%E5%91%98%22%5D%0A%20%20P1%20--%3E%20X%5B%22%E5%90%84%E8%87%AA%E6%89%A7%E8%A1%8C%E9%BB%98%E8%AE%A4%E5%A4%84%E7%90%86%E9%80%80%E5%87%BA%E6%88%96%E8%A2%AB%E6%8D%95%E8%8E%B7%22%5D%0A%20%20P2%20--%3E%20X%0A%20%20P3%20--%3E%20X%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<p><span class="marginnote">上图回答「Ctrl-C 之后信号是怎么一步走到的」：终端驱动只查一个前台 PGID 字段，一次 <code>kill(-pgid)</code> 就完成整组投递，不必 shell 逐个 PID 去 kill。</span></p><p><span class="marginnote">初学者容易以为前台进程组「独占 CPU」、后台组被暂停就不占资源。实际上调度完全按进程/线程分配，与组无关；后台组只是读写终端时会被 <code>SIGTTIN</code>/<code>SIGTTOU</code> 停下，CPU 该跑照跑。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 System V 会话与 BSD 作业控制的历史分歧写完，不把 systemd 的 scope 当 OS 原语。窗口系统里的「前台」不是 tty 前台组。线程尚未从进程里拆开：下一课才在同一地址空间挂多条流。</p><p>后课默认：作业是进程组，会话绑 tty。同一份用户页上如何跑多条控制流，下一课讲<a href="/cs/thread-shared-addr">线程与共享地址空间</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>进程组：一并发信号的作业；会话绑控制终端。</li><li>前台组读写 tty；组不是调度实体。</li><li>同地址空间多控制流是下一课线程。</li><li>出处：Stevens and Rago, <em>APUE</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',7))])}const g=E(c,[["render",B]]);export{S as __pageData,g as default};
